{"content": "use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};

use super::validation::{
    validate_id_format, validate_range, validate_timestamp_not_future, Validate, ValidationError,
};

/// Represents the current state of a PWM-controlled fan
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct FanState {
    /// Unique identifier for the fan (e.g., "intake_fan", "exhaust_fan")
    pub fan_id: String,
    /// PWM duty cycle from 0.0 (off) to 1.0 (full speed)
    pub duty_cycle: f64,
    /// PWM frequency in Hz
    pub pwm_frequency_hz: u32,
    /// When this state was set
    pub timestamp: DateTime<Utc>,
    /// Whether this is a manual override or automatic control
    pub is_manual_override: bool,
}

impl FanState {
    /// Create a new fan state with validation
    pub fn new(
        fan_id: String,
        duty_cycle: f64,
        pwm_frequency_hz: u32,
        is_manual_override: bool,
    ) -> Result<Self, ValidationError> {
        let state = Self {
            fan_id,
            duty_cycle,
            pwm_frequency_hz,
            timestamp: Utc::now(),
            is_manual_override,
        };
        state.validate()?;
        Ok(state)
    }

    /// Create a fan state with a specific timestamp
    pub fn with_timestamp(
        fan_id: String,
        duty_cycle: f64,
        pwm_frequency_hz: u32,
        timestamp: DateTime<Utc>,
        is_manual_override: bool,
    ) -> Result<Self, ValidationError> {
        let state = Self {
            fan_id,
            duty_cycle,
            pwm_frequency_hz,
            timestamp,
            is_manual_override,
        };
        state.validate()?;
        Ok(state)
    }

    /// Create a fan state for turning the fan off
    pub fn off(fan_id: String) -> Result<Self, ValidationError> {
        Self::new(fan_id, 0.0, 1000, false) // Default 1kHz frequency when off
    }

    /// Create a fan state for running the fan at full speed
    pub fn full_speed(fan_id: String, pwm_frequency_hz: u32) -> Result<Self, ValidationError> {
        Self::new(fan_id, 1.0, pwm_frequency_hz, false)
    }

    /// Check if the fan is currently running (duty cycle > 0)
    pub fn is_running(&self) -> bool {
        self.duty_cycle > 0.0
    }

    /// Check if the fan is at full speed
    pub fn is_full_speed(&self) -> bool {
        self.duty_cycle >= 1.0
    }

    /// Get the duty cycle as a percentage (0-100)
    pub fn duty_cycle_percent(&self) -> f64 {
        self.duty_cycle * 100.0
    }

    /// Get the age of this state in seconds
    pub fn age_seconds(&self) -> i64 {
        (Utc::now() - self.timestamp).num_seconds()
    }

    /// Create a new state with the same parameters but updated duty cycle
    pub fn with_duty_cycle(&self, duty_cycle: f64) -> Result<Self, ValidationError> {
        Self::new(
            self.fan_id.clone(),
            duty_cycle,
            self.pwm_frequency_hz,
            self.is_manual_override,
        )
    }

    /// Create a new state marking it as manual override
    pub fn as_manual_override(&self) -> Result<Self, ValidationError> {
        Self::new(
            self.fan_id.clone(),
            self.duty_cycle,
            self.pwm_frequency_hz,
            true,
        )
    }

    /// Create a new state marking it as automatic control
    pub fn as_automatic(&self) -> Result<Self, ValidationError> {
        Self::new(
            self.fan_id.clone(),
            self.duty_cycle,
            self.pwm_frequency_hz,
            false,
        )
    }
}

impl Validate for FanState {
    fn validate(&self) -> Result<(), ValidationError> {
        // Validate fan ID format
        validate_id_format("fan_id", &self.fan_id)?;

        // Validate timestamp is not in the future
        validate_timestamp_not_future("timestamp", &self.timestamp)?;

        // Validate duty cycle range (0.0 to 1.0)
        validate_range("duty_cycle", self.duty_cycle, 0.0, 1.0)?;

        // Validate PWM frequency range (1Hz to 100kHz)
        validate_range(
            "pwm_frequency_hz",
            self.pwm_frequency_hz as f64,
            1.0,
            100000.0,
        )?;

        Ok(())
    }
}

impl std::fmt::Display for FanState {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let mode = if self.is_manual_override {
            "MANUAL"
        } else {
            "AUTO"
        };

        write!(
            f,
            "Fan {} at {}: {:.1}% ({:.0}Hz) [{}]",
            self.fan_id,
            self.timestamp.format("%H:%M:%S"),
            self.duty_cycle_percent(),
            self.pwm_frequency_hz,
            mode
        )
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use chrono::{Duration, Utc};

    #[test]
    fn test_fan_state_new() {
        let state = FanState::new(
            "intake_fan".to_string(),
            0.75,
            25000,
            false,
        );
        assert!(state.is_ok());

        let state = state.unwrap();
        assert_eq!(state.fan_id, "intake_fan");
        assert_eq!(state.duty_cycle, 0.75);
        assert_eq!(state.pwm_frequency_hz, 25000);
        assert!(!state.is_manual_override);
    }

    #[test]
    fn test_fan_state_validation() {
        // Valid state
        assert!(FanState::new("fan_1".to_string(), 0.5, 1000, false).is_ok());

        // Invalid fan ID
        assert!(FanState::new("".to_string(), 0.5, 1000, false).is_err());
        assert!(FanState::new("invalid-id".to_string(), 0.5, 1000, false).is_err());

        // Invalid duty cycle
        assert!(FanState::new("fan_1".to_string(), -0.1, 1000, false).is_err());
        assert!(FanState::new("fan_1".to_string(), 1.1, 1000, false).is_err());

        // Invalid PWM frequency
        assert!(FanState::new("fan_1".to_string(), 0.5, 0, false).is_err());
        assert!(FanState::new("fan_1".to_string(), 0.5, 200000, false).is_err());
    }

    #[test]
    fn test_fan_state_with_future_timestamp() {
        let future = Utc::now() + Duration::hours(1);
        let state = FanState::with_timestamp(
            "fan_1".to_string(),
            0.5,
            1000,
            future,
            false,
        );
        assert!(state.is_err());
    }

    #[test]
    fn test_fan_state_convenience_constructors() {
        // Test off
        let off_state = FanState::off("fan_1".to_string()).unwrap();
        assert_eq!(off_state.duty_cycle, 0.0);
        assert!(!off_state.is_running());

        // Test full speed
        let full_state = FanState::full_speed("fan_1".to_string(), 25000).unwrap();
        assert_eq!(full_state.duty_cycle, 1.0);
        assert!(full_state.is_full_speed());
        assert!(full_state.is_running());
    }

    #[test]
    fn test_fan_state_properties() {
        let state = FanState::new("fan_1".to_string(), 0.75, 25000, false).unwrap();

        assert!(state.is_running());
        assert!(!state.is_full_speed());
        assert_eq!(state.duty_cycle_percent(), 75.0);
    }

    #[test]
    fn test_fan_state_modifications() {
        let original = FanState::new("fan_1".to_string(), 0.5, 25000, false).unwrap();

        // Test duty cycle change
        let modified = original.with_duty_cycle(0.8).unwrap();
        assert_eq!(modified.duty_cycle, 0.8);
        assert_eq!(modified.fan_id, original.fan_id);

        // Test manual override
        let manual = original.as_manual_override().unwrap();
        assert!(manual.is_manual_override);

        // Test automatic
        let auto = manual.as_automatic().unwrap();
        assert!(!auto.is_manual_override);
    }

    #[test]
    fn test_age_seconds() {
        let past = Utc::now() - Duration::minutes(2);
        let state = FanState::with_timestamp(
            "fan_1".to_string(),
            0.5,
            1000,
            past,
            false,
        ).unwrap();

        let age = state.age_seconds();
        assert!(age >= 115 && age <= 125); // ~120 seconds ± 5 for test execution time
    }

    #[test]
    fn test_display() {
        let state = FanState::new("intake_fan".to_string(), 0.75, 25000, true).unwrap();
        let display = format!("{}", state);
        assert!(display.contains("intake_fan"));
        assert!(display.contains("75.0%"));
        assert!(display.contains("25000Hz"));
        assert!(display.contains("MANUAL"));
    }

    #[test]
    fn test_serialization() {
        let state = FanState::new("fan_1".to_string(), 0.5, 1000, false).unwrap();

        // Test serialization
        let json = serde_json::to_string(&state).unwrap();
        assert!(json.contains("fan_1"));
        assert!(json.contains("0.5"));
        assert!(json.contains("1000"));

        // Test deserialization
        let deserialized: FanState = serde_json::from_str(&json).unwrap();
        assert_eq!(state, deserialized);
    }
}", "filePath": "/Users/abe/Projects/rpi-smoker/backend/src/models/fan.rs"}

{"content": "use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};

use super::validation::{
    validate_id_format, validate_string_length, validate_timestamp_not_future, Validate,
    ValidationError,
};

/// Represents an alarm event that can be triggered by various conditions
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct AlarmEvent {
    /// Unique identifier for this alarm (e.g., "high_temp_alarm_1")
    pub alarm_id: String,
    /// Whether the alarm is currently triggered
    pub triggered: bool,
    /// The condition/formula that triggered this alarm
    pub condition: String,
    /// Human-readable message describing the alarm
    pub message: String,
    /// When this alarm event occurred
    pub timestamp: DateTime<Utc>,
    /// Whether the alarm has been acknowledged by a user
    pub acknowledged: bool,
    /// Number of times this alarm has been triggered in the current session
    pub trigger_count: u32,
}

impl AlarmEvent {
    /// Create a new alarm event with validation
    pub fn new(
        alarm_id: String,
        triggered: bool,
        condition: String,
        message: String,
    ) -> Result<Self, ValidationError> {
        let event = Self {
            alarm_id,
            triggered,
            condition,
            message,
            timestamp: Utc::now(),
            acknowledged: false,
            trigger_count: if triggered { 1 } else { 0 },
        };
        event.validate()?;
        Ok(event)
    }

    /// Create an alarm event with a specific timestamp
    pub fn with_timestamp(
        alarm_id: String,
        triggered: bool,
        condition: String,
        message: String,
        timestamp: DateTime<Utc>,
    ) -> Result<Self, ValidationError> {
        let event = Self {
            alarm_id,
            triggered,
            condition,
            message,
            timestamp,
            acknowledged: false,
            trigger_count: if triggered { 1 } else { 0 },
        };
        event.validate()?;
        Ok(event)
    }

    /// Create a triggered alarm event
    pub fn triggered(
        alarm_id: String,
        condition: String,
        message: String,
    ) -> Result<Self, ValidationError> {
        Self::new(alarm_id, true, condition, message)
    }

    /// Create a cleared alarm event (not triggered)
    pub fn cleared(
        alarm_id: String,
        condition: String,
        message: String,
    ) -> Result<Self, ValidationError> {
        Self::new(alarm_id, false, condition, message)
    }

    /// Acknowledge this alarm
    pub fn acknowledge(&mut self) {
        self.acknowledged = true;
    }

    /// Create a new alarm event with acknowledged status
    pub fn with_acknowledged(&self, acknowledged: bool) -> Self {
        let mut event = self.clone();
        event.acknowledged = acknowledged;
        event
    }

    /// Trigger this alarm (increment trigger count)
    pub fn trigger(&mut self) {
        self.triggered = true;
        self.trigger_count += 1;
        self.timestamp = Utc::now();
        self.acknowledged = false; // Reset acknowledgment when retriggered
    }

    /// Clear this alarm
    pub fn clear(&mut self) {
        self.triggered = false;
        self.timestamp = Utc::now();
        // Don't reset trigger_count or acknowledged status when clearing
    }

    /// Check if this alarm needs attention (triggered and not acknowledged)
    pub fn needs_attention(&self) -> bool {
        self.triggered && !self.acknowledged
    }

    /// Get the age of this alarm event in seconds
    pub fn age_seconds(&self) -> i64 {
        (Utc::now() - self.timestamp).num_seconds()
    }

    /// Get the severity level based on trigger count
    pub fn severity_level(&self) -> AlarmSeverity {
        match self.trigger_count {
            0 => AlarmSeverity::Info,
            1..=2 => AlarmSeverity::Warning,
            3..=5 => AlarmSeverity::High,
            _ => AlarmSeverity::Critical,
        }
    }

    /// Create a new alarm event with incremented trigger count
    pub fn with_incremented_trigger_count(&self) -> Self {
        let mut event = self.clone();
        event.trigger_count += 1;
        event.timestamp = Utc::now();
        event
    }
}

/// Alarm severity levels
#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq, PartialOrd, Ord)]
pub enum AlarmSeverity {
    Info,
    Warning,
    High,
    Critical,
}

impl std::fmt::Display for AlarmSeverity {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            AlarmSeverity::Info => write!(f, "INFO"),
            AlarmSeverity::Warning => write!(f, "WARNING"),
            AlarmSeverity::High => write!(f, "HIGH"),
            AlarmSeverity::Critical => write!(f, "CRITICAL"),
        }
    }
}

impl Validate for AlarmEvent {
    fn validate(&self) -> Result<(), ValidationError> {
        // Validate alarm ID format
        validate_id_format("alarm_id", &self.alarm_id)?;

        // Validate timestamp is not in the future
        validate_timestamp_not_future("timestamp", &self.timestamp)?;

        // Validate condition is not empty
        if self.condition.is_empty() {
            return Err(ValidationError::EmptyField("condition".to_string()));
        }

        // Validate message length and content
        if self.message.is_empty() {
            return Err(ValidationError::EmptyField("message".to_string()));
        }
        validate_string_length("message", &self.message, 500)?;

        Ok(())
    }
}

impl std::fmt::Display for AlarmEvent {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let status = if self.triggered {
            if self.acknowledged {
                "TRIGGERED (ACK)"
            } else {
                "TRIGGERED"
            }
        } else {
            "CLEARED"
        };

        write!(
            f,
            "Alarm {} [{}] at {}: {} (count: {})",
            self.alarm_id,
            status,
            self.timestamp.format("%H:%M:%S"),
            self.message,
            self.trigger_count
        )
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use chrono::{Duration, Utc};

    #[test]
    fn test_alarm_event_new() {
        let event = AlarmEvent::new(
            "high_temp_alarm".to_string(),
            true,
            "temperature > 250".to_string(),
            "Temperature too high!".to_string(),
        );
        assert!(event.is_ok());

        let event = event.unwrap();
        assert_eq!(event.alarm_id, "high_temp_alarm");
        assert!(event.triggered);
        assert_eq!(event.trigger_count, 1);
        assert!(!event.acknowledged);
    }

    #[test]
    fn test_alarm_event_validation() {
        // Valid event
        assert!(AlarmEvent::new(
            "alarm_1".to_string(),
            true,
            "temp > 100".to_string(),
            "High temperature".to_string(),
        ).is_ok());

        // Invalid alarm ID
        assert!(AlarmEvent::new(
            "".to_string(),
            true,
            "temp > 100".to_string(),
            "High temperature".to_string(),
        ).is_err());

        // Empty condition
        assert!(AlarmEvent::new(
            "alarm_1".to_string(),
            true,
            "".to_string(),
            "High temperature".to_string(),
        ).is_err());

        // Empty message
        assert!(AlarmEvent::new(
            "alarm_1".to_string(),
            true,
            "temp > 100".to_string(),
            "".to_string(),
        ).is_err());

        // Message too long
        let long_message = "a".repeat(501);
        assert!(AlarmEvent::new(
            "alarm_1".to_string(),
            true,
            "temp > 100".to_string(),
            long_message,
        ).is_err());
    }

    #[test]
    fn test_alarm_event_convenience_constructors() {
        // Test triggered
        let triggered = AlarmEvent::triggered(
            "alarm_1".to_string(),
            "temp > 100".to_string(),
            "High temperature".to_string(),
        ).unwrap();
        assert!(triggered.triggered);
        assert_eq!(triggered.trigger_count, 1);

        // Test cleared
        let cleared = AlarmEvent::cleared(
            "alarm_1".to_string(),
            "temp <= 100".to_string(),
            "Temperature normal".to_string(),
        ).unwrap();
        assert!(!cleared.triggered);
        assert_eq!(cleared.trigger_count, 0);
    }

    #[test]
    fn test_alarm_event_acknowledge() {
        let mut event = AlarmEvent::triggered(
            "alarm_1".to_string(),
            "temp > 100".to_string(),
            "High temperature".to_string(),
        ).unwrap();

        assert!(!event.acknowledged);
        assert!(event.needs_attention());

        event.acknowledge();
        assert!(event.acknowledged);
        assert!(!event.needs_attention());
    }

    #[test]
    fn test_alarm_event_trigger_and_clear() {
        let mut event = AlarmEvent::cleared(
            "alarm_1".to_string(),
            "temp > 100".to_string(),
            "Temperature normal".to_string(),
        ).unwrap();

        assert!(!event.triggered);
        assert_eq!(event.trigger_count, 0);

        // Trigger the alarm
        event.trigger();
        assert!(event.triggered);
        assert_eq!(event.trigger_count, 1);
        assert!(!event.acknowledged);

        // Acknowledge and trigger again
        event.acknowledge();
        event.trigger();
        assert!(event.triggered);
        assert_eq!(event.trigger_count, 2);
        assert!(!event.acknowledged); // Should reset on retrigger

        // Clear the alarm
        event.clear();
        assert!(!event.triggered);
        assert_eq!(event.trigger_count, 2); // Count preserved
        assert!(!event.acknowledged); // Acknowledgment preserved
    }

    #[test]
    fn test_alarm_severity_levels() {
        let mut event = AlarmEvent::cleared(
            "alarm_1".to_string(),
            "condition".to_string(),
            "message".to_string(),
        ).unwrap();

        // Test severity progression
        assert_eq!(event.severity_level(), AlarmSeverity::Info);

        event.trigger_count = 1;
        assert_eq!(event.severity_level(), AlarmSeverity::Warning);

        event.trigger_count = 3;
        assert_eq!(event.severity_level(), AlarmSeverity::High);

        event.trigger_count = 10;
        assert_eq!(event.severity_level(), AlarmSeverity::Critical);
    }

    #[test]
    fn test_alarm_with_future_timestamp() {
        let future = Utc::now() + Duration::hours(1);
        let event = AlarmEvent::with_timestamp(
            "alarm_1".to_string(),
            true,
            "condition".to_string(),
            "message".to_string(),
            future,
        );
        assert!(event.is_err());
    }

    #[test]
    fn test_age_seconds() {
        let past = Utc::now() - Duration::minutes(3);
        let event = AlarmEvent::with_timestamp(
            "alarm_1".to_string(),
            true,
            "condition".to_string(),
            "message".to_string(),
            past,
        ).unwrap();

        let age = event.age_seconds();
        assert!(age >= 175 && age <= 185); // ~180 seconds ± 5 for test execution time
    }

    #[test]
    fn test_display() {
        let mut event = AlarmEvent::triggered(
            "high_temp_alarm".to_string(),
            "temp > 250".to_string(),
            "Temperature too high!".to_string(),
        ).unwrap();

        let display = format!("{}", event);
        assert!(display.contains("high_temp_alarm"));
        assert!(display.contains("TRIGGERED"));
        assert!(display.contains("Temperature too high!"));
        assert!(display.contains("count: 1"));

        event.acknowledge();
        let display = format!("{}", event);
        assert!(display.contains("TRIGGERED (ACK)"));
    }

    #[test]
    fn test_serialization() {
        let event = AlarmEvent::triggered(
            "alarm_1".to_string(),
            "temp > 100".to_string(),
            "High temperature".to_string(),
        ).unwrap();

        // Test serialization
        let json = serde_json::to_string(&event).unwrap();
        assert!(json.contains("alarm_1"));
        assert!(json.contains("temp > 100"));
        assert!(json.contains("High temperature"));

        // Test deserialization
        let deserialized: AlarmEvent = serde_json::from_str(&json).unwrap();
        assert_eq!(event, deserialized);
    }
