        stats.update_with_state(&state1);
        assert_eq!(stats.state_changes, 1);
        assert_eq!(stats.avg_duty_cycle, 0.5);
        assert!(stats.is_currently_running());

        // Test second state (after some time)
        let mut state2 = FanState::new(
            "fan_1".to_string(),
            0.8,
            1000,
            false,
