            if self.acknowledged {
                "TRIGGERED (ACK)"
            } else {
                "TRIGGERED"
            }
        } else {
            "CLEARED"
        };

        write!(
            f,
            "Alarm {} [{}] at {}: {} (count: {})",
            self.alarm_id,
            status,
            self.timestamp.format("%H:%M:%S"),
            self.message,
            self.trigger_count
        )
    }
}
