    /// Trigger this alarm (increment trigger count)
    pub fn trigger(&mut self) {
        self.triggered = true;
        self.trigger_count += 1;
        self.timestamp = Utc::now();
        self.acknowledged = false; // Reset acknowledgment when retriggered
    }

