    pub fn needs_attention(&self) -> bool {
        self.triggered && !self.acknowledged
    }

    /// Get the age of this alarm event in seconds
    pub fn age_seconds(&self) -> i64 {
        (Utc::now() - self.timestamp).num_seconds()
    }
